CREATE DATABASE IF NOT EXISTS medora_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE medora_db;

CREATE TABLE IF NOT EXISTS eczaneler (
    eczane_id CHAR(36) PRIMARY KEY,
    ad VARCHAR(150),
    adres TEXT,
    sehir VARCHAR(100),
    ilce VARCHAR(100),
    telefon VARCHAR(255),
    enlem VARCHAR(50),
    boylam VARCHAR(50)
);

